return {
    lerp = function(p1, p2, p3) -- lerp | line: 11
        return p1 + (p2 - p1) * p3
    end,
    map = function(p4, p5, p6, p7, p8) -- map | line: 25
        return (p4 - p5) * (p8 - p7) / (p6 - p5) + p7
    end,
    blend = function(...) -- blend | line: 37
        local n1 = 1

        for _, v1 in { ... } do
            n1 *= 1 - v1
        end

        return 1 - n1
    end
}
